const input = $input.first().json;
const filas = Array.isArray(input.filas) ? input.filas : [];
const DIAS = ['LUN','MAR','MIE','JUE','VIE','SAB'];
const FORMATOS = ['Presencial','Semipresencial'];
const TIPOS = ['Normal','Híbrido'];
const HORA = /^([01]\d|2[0-3]):[0-5]\d$/;

function limpio(v){ if(v==null) return null; const t=String(v).trim(); return t.length?t:null; }
function hora(v){ const t=limpio(v); if(!t) return null; return t.length===5?t:t.slice(0,5); }
function normalizarDia(v){
  const t = limpio(v); if(!t) return null;
  const n = t.toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const mapa = {LUN:'LUN',LUNES:'LUN',MAR:'MAR',MARTES:'MAR',MIE:'MIE',MIER:'MIE',MIERCOLES:'MIE',JUE:'JUE',JUEV:'JUE',JUEVES:'JUE',VIE:'VIE',VIER:'VIE',VIERNES:'VIE',SAB:'SAB',SABADO:'SAB'};
  if(mapa[n]) return mapa[n];
  const p3 = n.slice(0,3);
  if(mapa[p3]) return mapa[p3];
  return n;
}
function normalizarTipo(v){
  const t=limpio(v); if(!t) return null;
  const n=t.toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(n==='NORMAL') return 'Normal';
  if(n==='HIBRIDO' || n==='HIBRIDA') return 'Híbrido';
  return t;
}
function normalizarFormato(v){
  const t=limpio(v); if(!t) return null;
  const n=t.toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(n==='PRESENCIAL') return 'Presencial';
  if(n==='SEMIPRESENCIAL') return 'Semipresencial';
  return t;
}

if(filas.length===0) return [{json:{ok:false,errores:['Debe registrar al menos una fila de programación.'],filas:[]}}];
if(filas.length>200) return [{json:{ok:false,errores:['El máximo permitido es 200 filas por versión.'],filas:[]}}];

const errores=[]; const normalizadas=[]; const vistos=new Map();
filas.forEach((fila, idx)=>{
  const nFila=idx+1;
  const claveCurso = (limpio(fila.clave_curso ?? fila.claveCurso ?? fila.clave) || '').toUpperCase();
  const nombreCurso = limpio(fila.nombre_curso ?? fila.nombreCurso);
  const secuencia = limpio(fila.secuencia);
  const horario = (limpio(fila.horario) || '').toUpperCase();
  const vacantesNum = Number(fila.vacantes);
  const vacantes = Number.isFinite(vacantesNum) ? Math.trunc(vacantesNum) : NaN;
  const docentes = limpio(fila.docentes);
  const dia = normalizarDia(fila.dia);
  const horaInicio = hora(fila.hora_inicio ?? fila.horaInicio);
  const horaFin = hora(fila.hora_fin ?? fila.horaFin);
  const formatoCurso = normalizarFormato(fila.formato_curso ?? fila.formatoCurso ?? fila.formato);
  const tipoAulaSolicitado = normalizarTipo(fila.tipo_aula_solicitado ?? fila.tipoAulaSolicitado ?? fila.tipo_aula ?? fila.tipoAula);
  const facultadPrograma = limpio(fila.facultad_programa ?? fila.facultadPrograma ?? fila.facultad);
  const observacionesFacultad = limpio(fila.observaciones_facultad ?? fila.observacionesFacultad ?? fila.observaciones);

  if(!claveCurso) errores.push(`Fila ${nFila}: la clave del curso es obligatoria.`);
  if(horario.length < 3) errores.push(`Fila ${nFila}: el horario debe tener al menos 3 caracteres.`);
  if(!Number.isInteger(vacantes) || vacantes < 1) errores.push(`Fila ${nFila}: las vacantes deben ser un entero mayor o igual a 1.`);
  if(dia && !DIAS.includes(dia)) errores.push(`Fila ${nFila}: el día "${dia}" no es válido. Use LUN, MAR, MIE, JUE, VIE o SAB.`);
  if(horaInicio && !HORA.test(horaInicio)) errores.push(`Fila ${nFila}: la hora de inicio debe tener formato HH:mm (24 horas).`);
  if(horaFin && !HORA.test(horaFin)) errores.push(`Fila ${nFila}: la hora de fin debe tener formato HH:mm (24 horas).`);
  if(horaInicio && horaFin && horaFin <= horaInicio) errores.push(`Fila ${nFila}: la hora de fin debe ser posterior a la hora de inicio.`);
  if(formatoCurso && !FORMATOS.includes(formatoCurso)) errores.push(`Fila ${nFila}: el formato "${formatoCurso}" no es válido.`);
  if(tipoAulaSolicitado && !TIPOS.includes(tipoAulaSolicitado)) errores.push(`Fila ${nFila}: el tipo de aula "${tipoAulaSolicitado}" no es válido.`);
  if(!facultadPrograma) errores.push(`Fila ${nFila}: la facultad/programa es obligatoria.`);

  if(claveCurso && dia && horaInicio){
    const k = `${claveCurso}|${dia}|${horaInicio}|${horario}|${secuencia||''}`;
    if(vistos.has(k)) errores.push(`Fila ${nFila}: duplica la programación de la fila ${vistos.get(k)}.`);
    else vistos.set(k, nFila);
  }

  normalizadas.push({
    claveCurso, nombreCurso, secuencia, horario, vacantes: Number.isInteger(vacantes)?vacantes:0,
    docentes, dia, horaInicio, horaFin, formatoCurso, tipoAulaSolicitado, facultadPrograma: facultadPrograma||'', observacionesFacultad
  });
});

return [{json:{ok: errores.length===0, errores, filas: normalizadas}}];
